      .s_axi_control_RRESP(),
      .s_axi_control_RVALID(rvalid),
      .s_axi_control_RREADY(rready),
      .interrupt(interrupt));

  integer i;
  reg [31:0] status;

  task wr(input [31:0] a, input [31:0] d);
    begin
      @(negedge ap_clk); awaddr <= a[6:0]; wdata <= d;
      awvalid <= 1; wvalid <= 1; bready <= 1;
      @(posedge ap_clk);
      while (!(awready && wready)) @(posedge ap_clk);
      @(negedge ap_clk); awvalid <= 0; wvalid <= 0;
      @(posedge ap_clk);
    end
  endtask

  task rd(input [31:0] a, output [31:0] d);
    begin
      @(negedge ap_clk); araddr <= a[6:0]; arvalid <= 1; rready <= 1;
      @(posedge ap_clk);
      while (!arready) @(posedge ap_clk);
      @(negedge ap_clk); arvalid <= 0;
      while (!rvalid) @(posedge ap_clk);
      d = rdata;
      @(posedge ap_clk);
    end
  endtask

  // Cycles the kernel spends moving data: the first beat any master
  // moves to the last. The control writes, the start bit and the
  // polling that follows all sit outside it, so this is the same
  // quantity another flow reads off a waveform rather than the
  // number its own testbench reports.
  integer data_cyc = 0; integer first_beat = -1; integer last_beat = -1;
  always @(posedge ap_clk) if (ap_rst_n) begin
    data_cyc = data_cyc + 1;
    if (u_ram0.RVALID && u_ram0.RREADY) begin
      if (first_beat < 0) first_beat = data_cyc;
      last_beat = data_cyc;
    end
    if (u_ram1.RVALID && u_ram1.RREADY) begin
      if (first_beat < 0) first_beat = data_cyc;
      last_beat = data_cyc;
    end
    if (u_ram2.WVALID && u_ram2.WREADY) begin
      if (first_beat < 0) first_beat = data_cyc;
      last_beat = data_cyc;
    end
  end

  initial begin
    awvalid = 0; wvalid = 0; bready = 0; arvalid = 0; rready = 0;
    awaddr = 0; wdata = 0; araddr = 0;
    repeat (8) @(posedge ap_clk);
    @(negedge ap_clk) ap_rst_n = 1;
    repeat (8) @(posedge ap_clk);

    // feed_mac_w_in_bind: 1024 bytes
    $readmemh("feed_mac_w_in_bind.hex", u_ram0.mem);
    // feed_mac_a_in_bind: 1024 bytes
    $readmemh("feed_mac_a_in_bind.hex", u_ram1.mem);

    wr(32'h10, 32'd0);
    wr(32'h14, 32'd0);
    wr(32'h18, 32'd0);
    wr(32'h1c, 32'd0);
    wr(32'h20, 32'd0);
    wr(32'h24, 32'd0);
    wr(32'h28, 32'd32);
    wr(32'h30, 32'd32);
    wr(32'h38, 32'd32);

    $display("SPMW TB: starting at %0t", $time);
    wr(32'h00, 32'd1);
    status = 0;
    for (i = 0; i < 200000 && !status[1]; i = i + 1) begin
      rd(32'h00, status);
    end
    if (!status[1]) begin
      $display("SPMW TB TIMEOUT after %0d polls at %0t, ctrl=%h", i, $time, status);
      $finish;
    end
    $display("SPMW TB: done after %0d poll(s) at %0t", i, $time);
    $display("SPMW TB DATA first_beat %0d last_beat %0d cycles %0d",
             first_beat, last_beat, last_beat - first_beat + 1);
    begin : compare
      integer bad;
      bad = 0;
      begin : expected_block
        reg [7:0] exp [0:4095];
        integer k;
        $readmemh("expected.hex", exp);
        for (k = 0; k < 4096; k = k + 1)
          if (u_ram2.mem[k] !== exp[k]) bad = bad + 1;
      end
      $display("SPMW TB RESULT %0d of %0d byte(s) wrong", bad, 4096);
    end
    $finish;
  end
endmodule
